  await expectText(page.locator('.radio', { hasText: 'Ukryty' }), 'Arkusz ukryty');
  await expectText(page.locator('[data-testid=import-size]'), '7 wierszy, 7 kolumn');

  // Pusty arkusz blokuje przejście dalej, inny arkusz je odblokowuje.
