  await page.screenshot({ path: path.join(OUTPUT, 'fiszki-156-ipad-strona-3.png') });
  await third.locator('.flashcard__line span').first().tap();
  await waitUntil(async () => (await side(page)) === 'front', 'Powrót do pytania');
